const input = $json;

const mode = input.mode || 'unknown';
const taskId = input.task_id || '';

let text = '';

if (mode === 'help') {
  text = `SEO Content Agent — команды

/run — полный pipeline:
SEO ТЗ → SEO текст → SEO QA → Factcheck

/outline — создать только SEO-ТЗ
/text — написать SEO-текст по ТЗ
/seoqa — проверить текст по ТЗ
/factcheck — проверить факты
/get task-id — получить сохранённый результат

Дополнительные флаги:
--strict — строгий режим без обещаний и рискованных формулировок
--tables yes — таблицы обязательны
--tables no — без таблиц
--from task-id — использовать сохранённый результат

Пример:

/run --strict
Тип: страница услуги
Тема: SEO-аудит сайта
Таблицы: да

Бриф:
Услуга SEO-аудита сайта.
В услугу входит техническая проверка, анализ структуры, контента и индексации.
Без гарантий.
Без сроков.`;
} else if (mode === 'start') {
  text = `SEO Content Agent

Я помогаю готовить SEO-ТЗ, SEO-тексты, QA-проверку и factcheck по заданному брифу.

Что умею:
— создавать SEO-ТЗ;
— писать SEO-тексты;
— проверять текст по ТЗ;
— проверять факты и рискованные формулировки;
— работать в строгом режиме без обещаний и гарантий;
— сохранять результаты по Task ID.

Основные команды:
/run — полный pipeline
/outline — только SEO-ТЗ
/text — только SEO-текст
/seoqa — SEO QA
/factcheck — фактчек
/get task-id — получить результат
/help — справка по командам

Для полного запуска отправьте:

/run --strict
Тип: страница услуги
Тема: SEO-аудит сайта
Таблицы: да

Бриф:
Опишите услугу, ограничения и важные требования.`;
} else {
  text = `Task ID: ${taskId}

Команда не распознана.

Используйте команды:
- /run — полный pipeline: ТЗ → текст → SEO QA → factcheck
- /outline — создать SEO-ТЗ
- /text — написать SEO-текст по ТЗ
- /seoqa — проверить текст по ТЗ
- /factcheck — проверить факты в тексте
- /get task-id — получить сохранённый результат
- /text --from task-id — написать текст по сохранённому ТЗ/результату
- /seoqa --from task-id — проверить сохранённый результат
- /help — показать подсказку`;
}

return [{
  json: {
    ...input,
    response_text: text
  }
}];

function extractContent(input) {
  if (input.choices?.[0]?.message?.content) return input.choices[0].message.content;
  if (input.body?.choices?.[0]?.message?.content) return input.body.choices[0].message.content;
  return '{}';
}

function parseJsonLoose(value) {
  if (typeof value !== 'string') return value || {};
  let text = value.trim();
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  return JSON.parse(text);
}

function arr(v) {
  return Array.isArray(v) ? v : [];
}

function splitMessage(text, maxLen = 3600) {
  const chunks = [];
  let rest = text;

  while (rest.length > maxLen) {
    let cut = rest.lastIndexOf('\n\n', maxLen);
    if (cut < 1000) cut = rest.lastIndexOf('\n', maxLen);
    if (cut < 1000) cut = maxLen;

    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }

  if (rest) chunks.push(rest);
  return chunks;
}

function lineObjectList(list, fields) {
  let out = '';

  arr(list).forEach((item, i) => {
    if (typeof item === 'string') {
      out += `${i + 1}. ${item}\n`;
    } else {
      out += `${i + 1}. ${fields.map(f => item?.[f]).filter(Boolean).join(' — ') || JSON.stringify(item)}\n`;
    }
  });

  return out;
}

let result = {};

try {
  result = parseJsonLoose(extractContent($json));
} catch (e) {
  result = {
    mode: $node['Route Command'].json.mode,
    verdict: 'reject',
    summary: 'Ошибка парсинга JSON от модели',
    problems: [String(e.message || e)],
    missing_data: []
  };
}

const route = $node['Route Command'].json;
const mode = route.mode || result.mode || 'outline';
const taskId = route.task_id;

const strictSource = [
  route.task_raw,
  route.task_input,
  route.restored_input,
  route.restored_output
].map(v => String(v || '')).join('\n');

const strictEnabled =
  route.strict === true ||
  route.flags?.strict === true ||
  route.reuse_context?.final_strict === true ||
  /(^|\s)--strict(\s|$)/i.test(strictSource);

let text = `Task ID: ${taskId}\n\n`;

if (mode === 'outline') {
  text += 'SEO ТЗ\n\n';
  text += `H1: ${result.h1 || '-'}\n\n`;

  if (arr(result.title_options).length) {
    text += 'Title options:\n';
    arr(result.title_options).slice(0, 3).forEach((title, i) => {
      text += `${i + 1}. ${title}\n`;
    });
    text += '\n';
  }

  if (result.meta_description) {
    text += `Meta description:\n${result.meta_description}\n\n`;
  }

  const tables = result.tables || {};
  text += 'Таблицы:\n';
  text += `Required: ${tables.required === true ? 'да' : 'нет'}\n`;

  if (tables.decision_reason) {
    text += `Причина: ${tables.decision_reason}\n`;
  }

  if (arr(tables.table_ideas).length) {
    text += 'Идеи таблиц:\n';
    text += lineObjectList(tables.table_ideas, ['title', 'purpose']);
  }

  text += '\n';
  text += 'Структура и ТЗ для копирайтера:\n\n';

  arr(result.sections).slice(0, 25).forEach((s, i) => {
    text += `${i + 1}. ${s.h2 || '-'}\n`;
    text += `Цель: ${s.goal || '-'}\n`;

    if (s.summary) {
      text += `Summary: ${s.summary}\n`;
    }

    text += `Объём: ${s.word_count || '-'}\n`;

    if (arr(s.keywords).length) {
      text += `Ключи: ${arr(s.keywords).slice(0, 10).join(', ')}\n`;
    }

    if (arr(s.entities).length) {
      const ents = arr(s.entities)
        .slice(0, 12)
        .map(e => typeof e === 'string' ? e : `${e.name || '-'} (${e.priority || '-'})`);

      text += `Сущности: ${ents.join(', ')}\n`;
    }

    if (arr(s.visual_elements).length) {
      text += `Визуальные элементы: ${arr(s.visual_elements).join(', ')}\n`;
    }

    if (arr(s.key_takeaways).length) {
      text += `Key takeaways: ${arr(s.key_takeaways).join('; ')}\n`;
    }

    text += `Заметки: ${s.copywriter_notes || '-'}\n\n`;
  });

  if (arr(result.entity_connections).length) {
    text += 'Entity connections:\n';
    text += lineObjectList(result.entity_connections, ['from', 'to', 'reason']);
    text += '\n';
  }

  if (arr(result.faq).length) {
    text += 'FAQ:\n';

    arr(result.faq).slice(0, 10).forEach((item, i) => {
      if (typeof item === 'string') {
        text += `${i + 1}. ${item}\n`;
      } else {
        text += `${i + 1}. ${item.question || '-'}\n`;

        if (item.answer_goal) {
          text += `   Цель ответа: ${item.answer_goal}\n`;
        }
      }
    });

    text += '\n';
  }

  if (result.cta) {
    text += `CTA:\n${result.cta}\n\n`;
  }

  if (result.qa) {
    text += `QA: ${result.qa.verdict || '-'}\n`;

    if (result.qa.summary) {
      text += `Резюме QA: ${result.qa.summary}\n`;
    }
  }
}

if (mode === 'text') {
  text += 'SEO Текст\n\n';

  const h1 = String(result.h1 || '').trim();
  let content = String(result.content_markdown || '').trim();

  if (h1 && content) {
    const h1Escaped = h1.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const duplicateH1Re = new RegExp(`^#\\s+${h1Escaped}\\s*\\n+`, 'i');
    content = content.replace(duplicateH1Re, '').trim();
  }

  if (h1) {
    text += `# ${h1}\n\n`;
  }

  text += content || '-';

  text += `\n\nТаблицы использованы: ${result.tables_used === true ? 'да' : 'нет'}\n`;

  if (arr(result.entities_used).length) {
    text += `Сущности использованы: ${arr(result.entities_used).join(', ')}\n`;
  }

  if (result.qa) {
    text += `\nQA: ${result.qa.verdict || '-'}\n`;

    if (result.qa.summary) {
      text += `Резюме QA: ${result.qa.summary}\n`;
    }
  }
}

if (mode === 'seoqa') {
  const summary = String(result.summary || '').toLowerCase();

  const hasProblems =
    (Array.isArray(result.problems) && result.problems.length > 0) ||
    (Array.isArray(result.fixes) && result.fixes.length > 0) ||
    summary.includes('implied-result') ||
    summary.includes('risky') ||
    summary.includes('рискован') ||
    summary.includes('замечание') ||
    summary.includes('может быть воспринят') ||
    summary.includes('может быть воспринята') ||
    summary.includes('рекомендуется заменить') ||
    summary.includes('намёк') ||
    summary.includes('намек');

  if (strictEnabled && hasProblems && result.verdict === 'ok') {
    result.verdict = 'warning';

    if (typeof result.score === 'number' && result.score > 89) {
      result.score = 89;
    }

    if (!Array.isArray(result.problems)) {
      result.problems = [];
    }

    if (!result.problems.length) {
      result.problems.push(
        'Strict QA: обнаружены implied-result formulations.'
      );
    }

    if (result.summary) {
result.summary =
  'Автопроверка: verdict понижен до warning, потому что в strict-режиме найдено замечание или implied-result formulation.\n\n' +
  result.summary;
    }
  }

  text += 'SEO QA\n\n';
  text += `Вердикт: ${result.verdict || '-'}\n`;
  text += `Оценка: ${result.score ?? '-'}\n`;

  if (result.summary) {
    text += `\nРезюме:\n${result.summary}\n`;
  }

  if (arr(result.sections_coverage).length) {
    text += '\nПокрытие секций:\n';

    arr(result.sections_coverage).slice(0, 20).forEach((p, i) => {
      text += `${i + 1}. ${typeof p === 'string' ? p : JSON.stringify(p)}\n`;
    });
  }

  if (result.tables_check) {
    text += `\nПроверка таблиц:\n${result.tables_check}\n`;
  }

  if (result.entities_check) {
    text += `\nПроверка сущностей:\n${result.entities_check}\n`;
  }

  if (arr(result.problems).length) {
    text += '\nПроблемы:\n';

    arr(result.problems).slice(0, 20).forEach((p, i) => {
      text += `${i + 1}. ${typeof p === 'string' ? p : JSON.stringify(p)}\n`;
    });
  }

  if (arr(result.fixes).length) {
    text += '\nЧто исправить:\n';

    arr(result.fixes).slice(0, 20).forEach((f, i) => {
      text += `${i + 1}. ${typeof f === 'string' ? f : JSON.stringify(f)}\n`;
    });
  }
}

if (mode === 'factcheck') {
  const hasRisky =
    (Array.isArray(result.risky_claims) && result.risky_claims.length > 0) ||
    (Array.isArray(result.unsupported_claims) && result.unsupported_claims.length > 0);

  if (strictEnabled && hasRisky && result.verdict === 'ok') {
    result.verdict = 'warning';

    if (result.summary) {
      result.summary =
        '[AUTO-FACTCHECK-CORRECTION] Verdict автоматически понижен до warning.\n\n' +
        result.summary;
    }
  }

  text += 'Factcheck\n\n';
  text += `Вердикт: ${result.verdict || '-'}\n`;

  if (result.summary) {
    text += `\nРезюме:\n${result.summary}\n`;
  }

  if (arr(result.risky_claims).length) {
    text += '\nРискованные утверждения:\n';

    arr(result.risky_claims).slice(0, 20).forEach((p, i) => {
      text += `${i + 1}. ${typeof p === 'string' ? p : JSON.stringify(p)}\n`;
    });
  }

  if (arr(result.unsupported_claims).length) {
    text += '\nНе подтверждено:\n';

    arr(result.unsupported_claims).slice(0, 20).forEach((p, i) => {
      text += `${i + 1}. ${typeof p === 'string' ? p : JSON.stringify(p)}\n`;
    });
  }

  if (arr(result.recommended_removals).length) {
    text += '\nЛучше убрать:\n';

    arr(result.recommended_removals).slice(0, 20).forEach((p, i) => {
      text += `${i + 1}. ${typeof p === 'string' ? p : JSON.stringify(p)}\n`;
    });
  }
}

if (arr(result.missing_data).length) {
  text += '\n\nПробелы данных:\n';

  arr(result.missing_data).slice(0, 15).forEach((item) => {
    text += `- ${item}\n`;
  });
}

if (mode === 'factcheck') {
  text += '\n\nПроверка выполнена по переданному тексту и доступному контексту.';
}

const chunks = splitMessage(text);

return chunks.map((chunk, index) => ({
  json: {
    chat_id: route.chat_id,
    telegram_text: chunks.length > 1 ? `[Часть ${index + 1}/${chunks.length}]\n\n${chunk}` : chunk,
    chunk_index: index,
    chunk_count: chunks.length,
    full_output_text: text,
    task_id: taskId,
    mode: mode,
    task_raw: route.task_raw || route.task_input || ''
  }
}));

function extractContent(input) {
  if (input.choices?.[0]?.message?.content) return input.choices[0].message.content;
  if (input.body?.choices?.[0]?.message?.content) return input.body.choices[0].message.content;
  return '{}';
}
function parseJsonLoose(value) {
  if (typeof value !== 'string') return value || {};
  let text = value.trim();
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  return JSON.parse(text);
}
function safeParse(value, fallbackMode) {
  try { return parseJsonLoose(value); }
  catch (e) {
    return {
      mode: fallbackMode,
      h1: '',
      title_options: [],
      meta_description: '',
      sections: [],
      tables: { required: false, decision_reason: 'Ошибка парсинга JSON от модели', table_ideas: [] },
      entity_connections: [],
      faq: [],
      cta: '',
      missing_data: ['Ошибка парсинга JSON от модели'],
      internal_risks: [String(e.message || e)]
    };
  }
}

const outline = safeParse(extractContent($json), 'outline');
const route = $node['Route Command'].json;

return [{
  json: {
    chat_id: route.chat_id,
    task_id: route.task_id,
    task_raw: route.task_raw || '',
    task_input: route.task_input,
    flags: route.flags || {},
    strict: !!route.strict,
    no_factcheck: !!route.no_factcheck,
    outline_only: !!route.outline_only,
    text_only: !!route.text_only,
    tables_policy: route.tables_policy || 'auto',
    outline
  }
}];

function extractContent(input) {
  if (input.choices?.[0]?.message?.content) return input.choices[0].message.content;
  if (input.body?.choices?.[0]?.message?.content) return input.body.choices[0].message.content;
  return '{}';
}
function parseJsonLoose(value) {
  if (typeof value !== 'string') return value || {};
  let text = value.trim();
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  return JSON.parse(text);
}
function safeParse(value) {
  try { return parseJsonLoose(value); }
  catch (e) {
    return {
      mode: 'text',
      h1: '',
      content_markdown: '',
      used_sections: [],
      tables_used: false,
      entities_used: [],
      qa: { verdict: 'reject', summary: 'Ошибка парсинга JSON от модели', issues: [String(e.message || e)] },
      missing_data: ['Ошибка парсинга JSON от модели']
    };
  }
}

const prev = $node['Extract SEO Strategy'].json;
const generated_text = safeParse(extractContent($json));

return [{
  json: {
    chat_id: prev.chat_id,
    task_id: prev.task_id,
    task_raw: prev.task_raw || '',
    task_input: prev.task_input,
    flags: prev.flags || {},
    strict: !!prev.strict,
    no_factcheck: !!prev.no_factcheck,
    outline_only: !!prev.outline_only,
    text_only: !!prev.text_only,
    tables_policy: prev.tables_policy || 'auto',
    outline: prev.outline,
    seo_strategy: prev.seo_strategy || {},
    generated_text
  }
}];

function extractContent(input) {
  if (input.choices?.[0]?.message?.content) return input.choices[0].message.content;
  if (input.body?.choices?.[0]?.message?.content) return input.body.choices[0].message.content;
  return '{}';
}

function parseJsonLoose(value) {
  if (typeof value !== 'string') return value || {};
  let text = value.trim();
  text = text.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  return JSON.parse(text);
}

function safeParse(value) {
  try {
    return parseJsonLoose(value);
  } catch (e) {
    return {
      mode: 'seoqa',
      verdict: 'reject',
      score: 0,
      summary: 'Ошибка парсинга JSON от модели',
      sections_coverage: [],
      tables_check: '',
      entities_check: '',
      problems: [String(e.message || e)],
      fixes: ['Повторить генерацию или проверить OpenRouter response_format'],
      unsupported_requirements_ignored: [],
      missing_data: []
    };
  }
}

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueStrings(list) {
  return [...new Set(
    arr(list)
      .map(item => String(item || '').trim())
      .filter(Boolean)
  )];
}

function normalizeVerdict(value) {
  const v = String(value || '').trim().toLowerCase().replace(/-/g, '_');

  if (['ok', 'approved', 'approve', 'pass', 'passed'].includes(v)) return 'approved';
  if (['warning', 'approved_with_warnings', 'warn'].includes(v)) return 'warning';
  if (['reject', 'rejected', 'fail', 'failed'].includes(v)) return 'reject';

  return v || 'reject';
}

const prev = $node['Restore Content Score Data']?.json || $node['Compute Content Score']?.json || {};
const seoqa = safeParse(extractContent($json));

seoqa.verdict = normalizeVerdict(seoqa.verdict);

const strictRiskScan = prev.strict_risk_scan || {};
const strictRiskCount = Number(strictRiskScan.count || 0);
const strictRiskViolations = uniqueStrings(strictRiskScan.violations || []);
const strictRiskLabels = uniqueStrings(strictRiskScan.labels || []);

if (!Array.isArray(seoqa.problems)) seoqa.problems = [];
if (!Array.isArray(seoqa.fixes)) seoqa.fixes = [];
if (!Array.isArray(seoqa.missing_data)) seoqa.missing_data = [];
if (!Array.isArray(seoqa.sections_coverage)) seoqa.sections_coverage = [];
if (!Array.isArray(seoqa.unsupported_requirements_ignored)) {
  seoqa.unsupported_requirements_ignored = [];
}

if (strictRiskCount > 0) {
  seoqa.verdict = 'reject';

  const currentScore = Number(seoqa.score);
  seoqa.score = Number.isFinite(currentScore)
    ? Math.min(currentScore, 70)
    : 70;

  const violationText = strictRiskViolations.length
    ? strictRiskViolations.join(', ')
    : 'strict risk markers detected';

  const labelText = strictRiskLabels.length
    ? ` Категории: ${strictRiskLabels.join(', ')}.`
    : '';

  seoqa.problems = uniqueStrings([
    ...seoqa.problems,
    `STRICT MODE violation: strict_risk_scan.count=${strictRiskCount}. Найдены рискованные формулировки: ${violationText}.${labelText}`
  ]);

  seoqa.fixes = uniqueStrings([
    ...seoqa.fixes,
    'Удалить или нейтрализовать рискованные формулировки из strict_risk_scan: заменить обещающие, оценочные и маркетинговые слова на проверяемые нейтральные формулировки.'
  ]);

  const prefix =
    `AUTO STRICT VALIDATOR: SEO QA понижен до reject, потому что strict_risk_scan.count=${strictRiskCount}. ` +
    `Оценка ограничена максимум 70.`;

  seoqa.summary = seoqa.summary
    ? `${prefix}\n\n${seoqa.summary}`
    : prefix;
}

return [{
  json: {
    chat_id: prev.chat_id,
    task_id: prev.task_id,
    task_raw: prev.task_raw || '',
    task_input: prev.task_input,
    flags: prev.flags || {},
    strict: !!prev.strict,
    no_factcheck: !!prev.no_factcheck,
    outline_only: !!prev.outline_only,
    text_only: !!prev.text_only,
    tables_policy: prev.tables_policy || 'auto',
    outline: prev.outline,
    seo_strategy: prev.seo_strategy || {},
    generated_text: prev.generated_text,
    content_score: prev.content_score || {},
    strict_cleanup: prev.strict_cleanup || {},
    table_sanity_check: prev.table_sanity_check || {},
    strict_risk_scan: strictRiskScan,
    seoqa
  }
}];

// v14-pc14-fu03-public-payload-consumer
function arrFu03(v) { return Array.isArray(v) ? v : []; }
function splitMessageFu03(text, maxLen = 3600) {
  const chunks = [];
