  while (rest.length > maxLen) {
    let cut = rest.lastIndexOf('\n\n', maxLen);
    if (cut < 1000) cut = rest.lastIndexOf('\n', maxLen);
    if (cut < 1000) cut = maxLen;
    chunks.push(rest.slice(0, cut).trim());
    rest = rest.slice(cut).trim();
  }
  if (rest) chunks.push(rest);
  return chunks;
}

if ($json.public_payload) {
  const pp = $json.public_payload;
  const surfaces = pp.surfaces || {};
  const meta = pp.meta || {};
  const taskId = meta.task_id || $json.task_id || '-';
  const qa = surfaces.seo_qa_public || {};
  const fc = surfaces.factcheck_public || {};

  let text = 'Task ID: ' + taskId + '\n\n';
  text += 'SEO Pipeline /run\n';
