const input = $json;
const VERSION = 'v1.1-tz-strict-cleanup-pc14-fu02-hotfix01';

const BP = '(^|[^\\p{L}\\p{N}_])';
const BS = '(?=$|[^\\p{L}\\p{N}_])';

const meta = {
  version: VERSION,
  count: 0,
  families: [],
  fields: [],
  skipped_empty: [],
};

const FAMILY_MARKERS = [
  ['аккуратн', /аккуратн/iu],
  ['удобств', /удобств/iu],
  ['удобн', /удобн/iu],
  ['позволя', /позволя/iu],
  ['обеспеч', /обеспеч/iu],
  ['контрол', /контрол/iu],
  ['безопасн', /безопасн/iu],
  ['специализирован', /специализирован/iu],
  ['надежн', /над[её]жн/iu],
];

function noteFamilyHits(before, after) {
  for (const [name, re] of FAMILY_MARKERS) {
    if (re.test(before) && !re.test(after) && !meta.families.includes(name)) {
      meta.families.push(name);
    }
  }
}

function rb(text, inner, to) {
  const re = new RegExp(`${BP}(${inner})${BS}`, 'giu');
  return text.replace(re, (m, p, w) => {
    meta.count += 1;
    return `${p}${typeof to === 'function' ? to(w) : to}`;
  });
}

const ACC_ENDINGS = {
  'ый': 'внимательный', 'ая': 'внимательная', 'ое': 'внимательное', 'ые': 'внимательные',
  'ого': 'внимательного', 'ой': 'внимательной', 'ому': 'внимательному', 'ым': 'внимательным',
  'ых': 'внимательных', 'ыми': 'внимательными', 'ую': 'внимательную', 'о': 'внимательно'
};
function mapAcc(word) {
  const w = String(word || '');
  if (/^аккуратно$/iu.test(w)) return 'внимательно';
  const m = w.match(/^аккуратн(.+)$/iu);
  if (m && ACC_ENDINGS[m[1].toLowerCase()]) return ACC_ENDINGS[m[1].toLowerCase()];
  return 'внимательный';
}

function mapUdobstv(word) {
  const w = String(word || '').toLowerCase();
  if (w === 'удобство') return 'наглядность';
  if (w === 'удобства') return 'наглядности';
  if (w === 'удобству') return 'наглядности';
  if (w === 'удобством') return 'наглядностью';
  return 'наглядность';
}

function mapUdobn(word) {
  const w = String(word || '');
  if (/^удобно$/iu.test(w)) return 'наглядно';
  if (/^удобный$/iu.test(w)) return 'понятный';
  if (/^удобная$/iu.test(w)) return 'понятная';
  if (/^удобное$/iu.test(w)) return 'понятное';
  if (/^удобные$/iu.test(w)) return 'понятные';
  if (/^удобного$/iu.test(w)) return 'понятного';
  if (/^удобных$/iu.test(w)) return 'понятных';
  if (/^удобному$/iu.test(w)) return 'понятному';
  if (/^удобными$/iu.test(w)) return 'понятными';
  if (/^удобной$/iu.test(w)) return 'понятной';
  return 'понятный';
}

function mapPozvolya(word) {
  const w = String(word || '').toLowerCase();
  if (w === 'позволяет') return 'дает возможность';
  if (w === 'позволяют') return 'дают возможность';
  if (w.startsWith('позволяющ')) return 'дающий возможность';
  if (w === 'позволять') return 'давать возможность';
  return 'дает возможность';
}

function cleanText(value) {
  let text = String(value || '');
  const original = text;

  // Phrase-first (FU-02 required examples + longer PC-14/FU-01 phrases)
  text = rb(text, 'для\\s+удобства\\s+восприятия', 'для структурированного представления');
  text = rb(text, 'удобства\\s+восприятия', 'структурированного представления');
  text = rb(text, 'что\\s+позволяет\\s+определить', 'за счет этого можно определить');
  text = rb(text, 'что\\s+позволяет\\s+оценить', 'за счет этого можно оценить');
  text = rb(text, 'для\\s+обеспечения\\s+безопасности\\s+перед\\s+работами', 'перед началом работ');
  text = rb(text, 'для\\s+обеспечения\\s+безопасности', 'для соблюдения требований работы');
  text = rb(text, 'обеспечение\\s+безопасности\\s+перед\\s+работами', 'отключение питания перед работами');
  text = rb(text, 'безопасность\\s+перед\\s+работами', 'подготовка перед работами');
  text = rb(text, 'техника\\s+безопасности', 'регламент перед работами');
  text = rb(text, 'требования\\s+безопасности', 'требования регламента');
  text = rb(text, 'обеспечение\\s+доступа\\s+к\\s+платам', 'доступ к платам');
  text = rb(text, 'для\\s+обеспечения\\s+доступа', 'для доступа');
  text = rb(text, 'обеспечение\\s+доступа', 'получение доступа');
  text = rb(text, 'обеспечение\\s+качества', 'проверка результата');

  text = rb(text, 'контролируются\\s+параметры', 'параметры фиксируются');
  text = rb(text, 'параметры\\s+контролируются', 'параметры фиксируются');
  text = rb(text, 'контроль\\s+качества', 'проверка результата');
  text = rb(text, 'контроль\\s+после\\s+сборки', 'проверка после сборки');
  text = rb(text, 'параметры\\s+контроля', 'проверяемые параметры');
  text = rb(text, 'метод\\s+контроля', 'метод проверки');
  text = rb(text, 'контроль\\s+давления', 'проверка давления');
  text = rb(text, 'контроль\\s+температуры', 'проверка температуры');

  text = rb(text, 'специализированными\\s+инструментами', 'профильными инструментами');
  text = rb(text, 'специализированные\\s+инструменты', 'профильные инструменты');
  text = rb(text, 'специализированный\\s+инструмент', 'профильный инструмент');
  text = rb(text, 'специализированное\\s+оборудование', 'профильное оборудование');
  text = rb(text, 'специализированные\\s+методы', 'профильные методы');
  text = rb(text, 'специализированные\\s+приборы', 'профильные приборы');

  text = rb(text, 'над[её]жность\\s+соединений', 'стабильность соединений');
  text = rb(text, 'над[её]жность\\s+работы', 'стабильность работы');
  text = rb(text, 'над[её]жная\\s+работа', 'стабильная работа');
  text = rb(text, 'над[её]жность', 'стабильность');

  // PC-14 R1 morphology / shorter phrases
  text = rb(text, 'для\\s+удобств(а|о)', 'для наглядности');
  text = rb(text, 'удобств(о|а|у|ом)', mapUdobstv);
  text = rb(text, 'удобн(ый|ая|ое|ые|ого|ых|ому|ыми|о)', mapUdobn);
  text = rb(text, 'аккуратн(ый|ая|ое|ые|ого|ых|ому|ыми|о|ой|ую)', mapAcc);
  text = rb(text, 'аккуратно', 'внимательно');
  text = rb(text, 'позволяет\\s+оценить', 'используется для оценки');
  text = rb(text, 'позволяет\\s+проверить', 'используется для проверки');
  text = rb(text, 'позволяет\\s+уточнить', 'используется для уточнения');
  text = rb(text, 'позволя(ет|ют|ющий|ющая|ющее|ющие|ющих|ть)', mapPozvolya);

  // Remaining stem families (safe short maps)
  text = rb(text, 'контроль', 'проверка');
  text = rb(text, 'контроля', 'проверки');
  text = rb(text, 'безопасн(ость|ости|остью|ый|ая|ое|ые|ого|ых)', (w) => {
    const s = String(w).toLowerCase();
    if (s.startsWith('безопасность')) return 'регламент работ';
    if (s.startsWith('безопасности')) return 'регламента работ';
    if (s.startsWith('безопасностью')) return 'регламентом работ';
    return 'регламентный';
  });
  text = rb(text, 'обеспеч(ение|ения|ению|ением|ить|ивает|ивают)', (w) => {
    const s = String(w).toLowerCase();
    if (s.startsWith('обеспечить')) return 'подготовить';
    if (s.startsWith('обеспечивает')) return 'поддерживает';
    if (s.startsWith('обеспечивают')) return 'поддерживают';
    return 'подготовка';
  });
  text = rb(text, 'специализированн(ыми|ые|ый|ая|ое|ых|ого|ому|ой|ую)', (w) => {
    const s = String(w).toLowerCase();
    if (s.endsWith('ыми')) return 'профильными';
    if (s.endsWith('ые')) return 'профильные';
    if (s.endsWith('ый')) return 'профильный';
    if (s.endsWith('ая')) return 'профильная';
    if (s.endsWith('ое')) return 'профильное';
    if (s.endsWith('ых')) return 'профильных';
    if (s.endsWith('ого')) return 'профильного';
    if (s.endsWith('ому')) return 'профильному';
    if (s.endsWith('ой')) return 'профильной';
    if (s.endsWith('ую')) return 'профильную';
    return 'профильные';
  });

  noteFamilyHits(original, text);
  return text;
}

function cleanStringField(obj, key, path) {
  if (!obj || typeof obj !== 'object' || Array.isArray(obj)) return;
  if (!(key in obj)) return;
  const val = obj[key];
  if (val == null) return;
  if (typeof val !== 'string') return;
  const before = val;
  if (!before.trim()) return;
  const after = cleanText(before);
  if (!String(after || '').trim()) {
    meta.skipped_empty.push(path);
    return;
  }
  if (after !== before) {
    obj[key] = after;
    meta.fields.push(path);
  }
}

function cleanStringArray(arr, path) {
  if (!Array.isArray(arr)) return;
  for (let i = 0; i < arr.length; i++) {
    const item = arr[i];
    if (typeof item === 'string') {
      const before = item;
      if (!before.trim()) continue;
      const after = cleanText(before);
      if (!String(after || '').trim()) {
        meta.skipped_empty.push(`${path}[${i}]`);
        continue;
      }
      if (after !== before) {
        arr[i] = after;
        meta.fields.push(`${path}[${i}]`);
      }
    } else if (item && typeof item === 'object') {
      cleanStringField(item, 'title', `${path}[${i}].title`);
      cleanStringField(item, 'purpose', `${path}[${i}].purpose`);
      cleanStringField(item, 'question', `${path}[${i}].question`);
      cleanStringField(item, 'answer_goal', `${path}[${i}].answer_goal`);
      cleanStringField(item, 'answer', `${path}[${i}].answer`);
      cleanStringField(item, 'reason', `${path}[${i}].reason`);
      cleanStringField(item, 'from', `${path}[${i}].from`);
      cleanStringField(item, 'to', `${path}[${i}].to`);
      cleanStringField(item, 'description', `${path}[${i}].description`);
      cleanStringField(item, 'name', `${path}[${i}].name`);
      cleanStringField(item, 'h2', `${path}[${i}].h2`);
      cleanStringField(item, 'summary', `${path}[${i}].summary`);
      if (Array.isArray(item.key_takeaways)) cleanStringArray(item.key_takeaways, `${path}[${i}].key_takeaways`);
      if (Array.isArray(item.visual_elements)) cleanStringArray(item.visual_elements, `${path}[${i}].visual_elements`);
      if (Array.isArray(item.keywords)) cleanStringArray(item.keywords, `${path}[${i}].keywords`);
      if (Array.isArray(item.entities)) {
        for (let j = 0; j < item.entities.length; j++) {
          const ent = item.entities[j];
          if (typeof ent === 'string') {
            const before = ent;
            const after = cleanText(before);
            if (after !== before && String(after || '').trim()) {
              item.entities[j] = after;
              meta.fields.push(`${path}[${i}].entities[${j}]`);
            }
          } else if (ent && typeof ent === 'object') {
            cleanStringField(ent, 'name', `${path}[${i}].entities[${j}].name`);
            cleanStringField(ent, 'description', `${path}[${i}].entities[${j}].description`);
          }
        }
      }
    }
  }
}

function clonePlain(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map(clonePlain);
  var out = {};
  Object.keys(value).forEach(function (key) {
    out[key] = clonePlain(value[key]);
  });
  return out;
}

function sanitizeOutline(outline) {
  if (!outline || typeof outline !== 'object') return outline;
  const o = clonePlain(outline);

  cleanStringField(o, 'h1', 'outline.h1');
  cleanStringField(o, 'meta_description', 'outline.meta_description');
  cleanStringField(o, 'cta', 'outline.cta');

  if (Array.isArray(o.title_options)) cleanStringArray(o.title_options, 'outline.title_options');

  if (o.tables && typeof o.tables === 'object') {
    cleanStringField(o.tables, 'decision_reason', 'outline.tables.decision_reason');
    if (Array.isArray(o.tables.table_ideas)) {
      cleanStringArray(o.tables.table_ideas, 'outline.tables.table_ideas');
    }
  }

  if (Array.isArray(o.sections)) cleanStringArray(o.sections, 'outline.sections');
  if (Array.isArray(o.faq)) cleanStringArray(o.faq, 'outline.faq');
  if (Array.isArray(o.entity_connections)) cleanStringArray(o.entity_connections, 'outline.entity_connections');

  return o;
}

const out = { ...input };
if (out.generated_text) {
  // Never mutate final SEO text at this stage (should be absent; defend anyway).
  out.generated_text = clonePlain(out.generated_text);
}

if (out.outline) {
  out.outline = sanitizeOutline(out.outline);
}

out.outline_strict_cleanup = {
  version: meta.version,
  count: meta.count,
  families: meta.families,
  fields: meta.fields,
  skipped_empty: meta.skipped_empty,
};
out.tz_strict_cleanup = out.outline_strict_cleanup;

return [{ json: out }];

const VERSION = 'v1-pc14-fu03-build-final-public-payload';
const NL_STRICT_RE = /не\s+используй\s+слова|запрещ[её]нные\s+слова|не\s+употребляй/iu;

function arr(v) { return Array.isArray(v) ? v : []; }
function clonePlain(v) { return JSON.parse(JSON.stringify(v)); }

function objectLine(item, fields) {
  if (typeof item === 'string') return item;
  return fields.map(f => item?.[f]).filter(Boolean).join(' — ') || JSON.stringify(item);
}

function detectNlStrict(brief) {
  const text = String(brief || '');
  return NL_STRICT_RE.test(text);
}

function extractCustomMarkers(brief) {
  const text = String(brief || '');
  const markers = [];
  const m = text.match(/(?:не\s+используй\s+слова|запрещ[её]нные\s+слова|не\s+употребляй)\s*[:：]?\s*([^.\n]+)/iu);
  if (!m) return markers;
  const chunk = m[1] || '';
  const parts = chunk.split(/[,;]|\s+и\s+/i).map(s => s.replace(/^[«"'\s]+|[»"'\s.]+$/g, '').trim()).filter(Boolean);
  for (let i = 0; i < parts.length; i++) {
    const token = parts[i];
    if (token.length < 3 || token.length > 64) continue;
    markers.push({ id: 'custom-' + i, label: token, stem: token, flags: 'giu', severity: 'custom', token: token });
  }
  return markers;
}

function buildSeoTz(outline) {
  const o = outline || {};
  const tables = o.tables || {};
  let text = '';
  text += 'H1: ' + (o.h1 || '-') + '\n\n';
  if (arr(o.title_options).length) {
    text += 'Title options:\n';
    arr(o.title_options).slice(0, 3).forEach((title, i) => { text += (i + 1) + '. ' + title + '\n'; });
    text += '\n';
  }
  if (o.meta_description) text += 'Meta description:\n' + o.meta_description + '\n\n';
  text += 'Таблицы:\n';
  text += 'Required: ' + (tables.required === true ? 'да' : 'нет') + '\n';
  if (tables.decision_reason) text += 'Причина: ' + tables.decision_reason + '\n';
  if (arr(tables.table_ideas).length) {
    text += 'Идеи таблиц:\n';
    arr(tables.table_ideas).slice(0, 8).forEach((item, i) => { text += (i + 1) + '. ' + objectLine(item, ['title', 'purpose']) + '\n'; });
  }
  text += '\nСтруктура:\n';
  arr(o.sections).slice(0, 20).forEach((s, i) => {
    text += (i + 1) + '. ' + (s.h2 || '-') + ' — ' + (s.word_count || '-') + ' слов\n';
    if (s.summary) text += '   Summary: ' + s.summary + '\n';
  });
  if (arr(o.faq).length) {
    text += '\nFAQ:\n';
    arr(o.faq).slice(0, 8).forEach((item, i) => {
      text += (i + 1) + '. ' + (typeof item === 'string' ? item : (item.question || '-')) + '\n';
    });
  }
  return text.trim();
}

function buildStrategyPublic(seoStrategy) {
  const s = seoStrategy || {};
  const lines = [];
  if (s.page_intent) lines.push('Intent: ' + s.page_intent);
  if (s.serp_pattern) lines.push('SERP pattern: ' + s.serp_pattern);
  if (s.content_angle) lines.push('Content angle: ' + s.content_angle);
  if (s.target_audience_focus) lines.push('Audience focus: ' + s.target_audience_focus);
  if (arr(s.priority_blocks).length) {
    lines.push('Priority blocks:');
    arr(s.priority_blocks).slice(0, 8).forEach((item, i) => {
      lines.push((i + 1) + '. ' + (typeof item === 'string' ? item : objectLine(item, ['name', 'reason'])));
    });
  }
  if (arr(s.snippet_opportunities).length) {
    lines.push('Snippet opportunities:');
    arr(s.snippet_opportunities).slice(0, 8).forEach((item, i) => {
      lines.push((i + 1) + '. ' + (typeof item === 'string' ? item : objectLine(item, ['type', 'block', 'reason'])));
    });
  }
  const ts = s.table_strategy;
  if (ts && typeof ts === 'object') {
    const titles = arr(ts.recommended_tables).map(t => t && t.title).filter(Boolean);
    if (titles.length) lines.push('Table titles: ' + titles.join('; '));
    if (ts.required === true) lines.push('Tables required: yes');
    // HIDE_RAW_STRATEGY_JSON: never dump reason / full table_strategy object
  } else if (typeof ts === 'string' && ts.trim()) {
    // If already stringified JSON, omit to avoid raw dump
    if (!(ts.trim().startsWith('{') || ts.trim().startsWith('['))) lines.push('Table strategy note: ' + ts);
  }
  if (arr(s.risk_notes).length) {
    lines.push('Risk notes:');
    arr(s.risk_notes).slice(0, 8).forEach((item, i) => {
      lines.push((i + 1) + '. ' + (typeof item === 'string' ? item : JSON.stringify(item)));
    });
  }
  return lines.join('\n').trim();
}

function extractTablesSummary(generated, outline) {
  const md = String((generated && generated.content_markdown) || '');
  const lines = md.split('\n').filter(l => /табл/i.test(l) && l.trim().length > 8).slice(0, 6);
  const reason = outline && outline.tables && outline.tables.decision_reason;
  const out = [];
  if (reason) out.push('TZ table reason: ' + reason);
  for (const l of lines) out.push(l.trim());
  return out.join('\n');
}

function composePreview(surfaces, taskId, meta) {
  let text = 'Task ID: ' + taskId + '\n\nSEO Pipeline /run\nТаблицы: ' + (meta.tables_policy || 'auto') + '\n\n';
  text += '=== 1. SEO ТЗ ===\n\n' + (surfaces.seo_tz || '-') + '\n\n';
  if (surfaces.seo_strategy_public) text += '=== SEO Strategy ===\n\n' + surfaces.seo_strategy_public + '\n\n';
  text += '=== 2. SEO Текст ===\n\n' + (surfaces.seo_text || '-') + '\n\n';
  const qa = surfaces.seo_qa_public || {};
  text += '=== 3. SEO QA ===\n\nВердикт: ' + (qa.verdict || '-') + '\nОценка: ' + ((qa.score ?? '-')) + '\n';
  if (qa.include_summary && qa.summary) text += 'Резюме: ' + qa.summary + '\n';
  text += '\n';
  const fc = surfaces.factcheck_public || {};
  text += '=== 4. Factcheck ===\n\nВердикт: ' + (fc.verdict || '-') + '\n';
  if (fc.include_summary && fc.summary) text += 'Резюме: ' + fc.summary + '\n';
  return [{ part_index: 0, text: text }];
}

