const STRICT_MARKER_SOT = {
  version: 'v1-pc14-fu03-strict-marker-sot',
  families: [
    { id: 'akuratn', label: 'аккуратн*', stem: 'аккуратн', flags: 'giu', severity: 'hard' },
    { id: 'udobstv', label: 'удобств*', stem: 'удобств', flags: 'giu', severity: 'hard' },
    { id: 'udobn', label: 'удобн*', stem: 'удобн', flags: 'giu', severity: 'hard' },
    { id: 'pozvolya', label: 'позволя*', stem: 'позволя', flags: 'giu', severity: 'hard' },
    { id: 'obespech', label: 'обеспеч*', stem: 'обеспеч', flags: 'giu', severity: 'hard' },
    { id: 'kontrol', label: 'контрол*', stem: 'контрол', flags: 'giu', severity: 'hard' },
    { id: 'bezopasn', label: 'безопасн*', stem: 'безопасн', flags: 'giu', severity: 'hard' },
    { id: 'specializ', label: 'специализирован*', stem: 'специализир', flags: 'giu', severity: 'hard' },
    { id: 'nadezhn', label: 'надежн* / надёжн*', stem: 'над[её]жн', flags: 'giu', severity: 'hard' },
    { id: 'naglyadn', label: 'наглядн*', stem: 'наглядн', flags: 'giu', severity: 'hard' }
  ]
};

function clonePlain(v) {
  return JSON.parse(JSON.stringify(v));
}

function escapeRegExp(s) {
  return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function compileFamily(family) {
  return {
    id: family.id,
    label: family.label,
    severity: family.severity || 'hard',
    re: new RegExp(family.stem, family.flags || 'giu')
  };
}

function snippetAround(text, index, len) {
  const start = Math.max(0, index - 40);
  const end = Math.min(text.length, index + len + 40);
  return text.slice(start, end).replace(/\s+/g, ' ').trim();
}

function scanText(text, families, surface, fieldPath) {
  const residuals = [];
  const raw = String(text || '');
  if (!raw) return residuals;
  for (const fam of families) {
    fam.re.lastIndex = 0;
    let m;
    while ((m = fam.re.exec(raw)) !== null) {
      residuals.push({
        marker_family_id: fam.id,
        marker_label: fam.label,
        match: m[0],
        surface: surface,
        field_path: fieldPath,
        snippet: snippetAround(raw, m.index, m[0].length),
        severity: fam.severity
      });
      if (m[0].length === 0) fam.re.lastIndex += 1;
      if (residuals.length > 200) return residuals;
    }
  }
  return residuals;
}

function buildFamilyList(customMarkers) {
  const families = STRICT_MARKER_SOT.families.map(compileFamily);
  const customs = Array.isArray(customMarkers) ? customMarkers : [];
  for (let i = 0; i < customs.length; i++) {
    const c = customs[i] || {};
    const stem = c.stem || c.token || c.label;
    if (!stem) continue;
    families.push(compileFamily({
      id: c.id || ('custom-' + i),
      label: c.label || String(stem),
      stem: escapeRegExp(String(stem)),
      flags: c.flags || 'giu',
      severity: 'custom'
    }));
  }
  return families;
}

function collectScanTargets(publicPayload) {
  const surfaces = (publicPayload && publicPayload.surfaces) || {};
  const targets = [];
  if (surfaces.seo_tz) targets.push({ surface: 'seo_tz', field_path: 'surfaces.seo_tz', text: surfaces.seo_tz });
  if (surfaces.seo_strategy_public) targets.push({ surface: 'seo_strategy_public', field_path: 'surfaces.seo_strategy_public', text: surfaces.seo_strategy_public });
  if (surfaces.seo_text) targets.push({ surface: 'seo_text', field_path: 'surfaces.seo_text', text: surfaces.seo_text });
  if (surfaces.tables_summary) targets.push({ surface: 'tables_summary', field_path: 'surfaces.tables_summary', text: surfaces.tables_summary });
  const qa = surfaces.seo_qa_public || {};
  if (qa.include_summary && qa.summary) {
    targets.push({ surface: 'seo_qa_public', field_path: 'surfaces.seo_qa_public.summary', text: qa.summary });
  }
  const fc = surfaces.factcheck_public || {};
  if (fc.include_summary && fc.summary) {
    targets.push({ surface: 'factcheck_public', field_path: 'surfaces.factcheck_public.summary', text: fc.summary });
  }
  const parts = ((publicPayload && publicPayload.telegram) || {}).parts_preview || [];
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i] || {};
    const t = p.text || p;
    if (t) targets.push({ surface: 'telegram_preview', field_path: 'telegram.parts_preview[' + i + '].text', text: t });
  }
  return targets;
}

function runStrictSurfaceScan(publicPayload, customMarkers, versionTag) {
  const families = buildFamilyList(customMarkers);
  const targets = collectScanTargets(publicPayload);
  const residuals = [];
  const surfacesScanned = [];
  for (const t of targets) {
    surfacesScanned.push(t.surface + ':' + t.field_path);
    const hits = scanText(t.text, families, t.surface, t.field_path);
    for (const h of hits) residuals.push(h);
  }
  const uniqueSurfaces = [];
  for (const t of targets) {
    if (uniqueSurfaces.indexOf(t.surface) === -1) uniqueSurfaces.push(t.surface);
  }
  const verdict = residuals.length ? 'dirty' : 'clean';
  return {
    version: versionTag || 'v1-pc14-fu03-final-surface-strict-scan',
    sot_version: STRICT_MARKER_SOT.version,
    verdict: verdict,
    count: residuals.length,
    residuals: residuals,
    surfaces_scanned: uniqueSurfaces,
    blocked: verdict === 'dirty',
    scanned_at: new Date().toISOString()
  };
}

