const VERSION = 'v1-pc14-fu03-build-strict-repair-payload';
const MAX_STRICT_SURFACE_REPAIR_ATTEMPTS = 1;
const input = $json;
const publicPayload = clonePlain(input.public_payload || {});
const meta = publicPayload.meta || {};
const attempts = Number(meta.repair_attempts || input.repair_attempts || 0);
const allowSecond = !!meta.allow_second_repair;
if (attempts >= MAX_STRICT_SURFACE_REPAIR_ATTEMPTS && !allowSecond) {
  // Still emit payload for graph continuity; extract/rescan will fail-closed if needed
}
const nextAttempts = Math.min(attempts + 1, MAX_STRICT_SURFACE_REPAIR_ATTEMPTS + (allowSecond ? 1 : 0));
meta.repair_attempts = nextAttempts;
publicPayload.meta = meta;

const scan = input.strict_surface_scan || {};
const residuals = scan.residuals || [];
const repairable = {};
for (const r of residuals) {
  const path = r.field_path || '';
  if (path.indexOf('surfaces.seo_strategy_public') === 0) repairable.seo_strategy_public = publicPayload.surfaces.seo_strategy_public;
  if (path.indexOf('surfaces.seo_tz') === 0) repairable.seo_tz = publicPayload.surfaces.seo_tz;
  if (path.indexOf('surfaces.seo_text') === 0) repairable.seo_text = publicPayload.surfaces.seo_text;
  if (path.indexOf('surfaces.tables_summary') === 0) repairable.tables_summary = publicPayload.surfaces.tables_summary;
  if (path.indexOf('surfaces.seo_qa_public.summary') === 0) {
    repairable.seo_qa_public = clonePlain(publicPayload.surfaces.seo_qa_public || {});
  }
  if (path.indexOf('surfaces.factcheck_public.summary') === 0) {
    repairable.factcheck_public = clonePlain(publicPayload.surfaces.factcheck_public || {});
  }
}

