function normalizeTablesPolicy(text) {
  const lower = String(text || '').toLowerCase();

  const cli = lower.match(/--tables\s+(yes|no|auto|да|нет|по-необходимости|по_необходимости|по необходимости)/i);
  if (cli) {
    const v = cli[1].replace(/[_-]/g, ' ');
    if (['yes', 'да'].includes(v)) return 'yes';
    if (['no', 'нет'].includes(v)) return 'no';
    return 'auto';
  }

  const ru = String(text || '').match(/таблиц[аы]?\s*:\s*([^\n\r]+)/i);
  if (ru) {
    const v = ru[1].trim().toLowerCase();
    if (/^(да|yes|true|нужн|обяз)/i.test(v)) return 'yes';
    if (/^(нет|no|false|не\s+нужн|без)/i.test(v)) return 'no';
    return 'auto';
  }

  return 'auto';
}

