function removeDuplicateH1(markdown) {
  const lines = String(markdown || '').split('\n');
  const result = [];

  let firstH1 = '';
  let h1Seen = false;

  for (const line of lines) {
    if (/^#\s+/.test(line)) {
      const current = normalizeHeading(line);

      if (!h1Seen) {
        firstH1 = current;
        h1Seen = true;
        result.push(line);
        continue;
      }

      if (current === firstH1) {
        continue;
      }
    }

    result.push(line);
  }

  return result.join('\n');
}

function replaceStrictMarkers(markdown) {
  let out = String(markdown || '');

  const replacements = [
    [/помогает/giu, 'используется для'],
    [/помогают/giu, 'используются для'],
    [/улучшает/giu, 'используется для корректировки'],
    [/улучшают/giu, 'используются для корректировки'],
    [/повышает/giu, 'учитывается при анализе'],
    [/повышают/giu, 'учитываются при анализе'],
    [/увеличивает/giu, 'фиксируется как изменение'],
    [/увеличивают/giu, 'фиксируются как изменения'],
    [/способствует/giu, 'относится к'],
    [/способствуют/giu, 'относятся к'],
    [/обеспечивает/giu, 'используется для'],
    [/обеспечивают/giu, 'используются для']
  ];

  for (const [from, to] of replacements) {
    out = out.replace(from, to);
  }

  return out;
}

