}];

const input = $json;

const generated = input.generated_text || {};
const h1 = String(generated.h1 || '').trim();

let text = String(
  generated.content_markdown ||
  generated['content-markdown'] ||
  generated.text ||
  ''
).trim();

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function uniqueStrings(list) {
  return [...new Set(
    arr(list)
      .map(item => String(item || '').trim())
      .filter(Boolean)
  )];
}

function normalize(value) {
  return String(value || '')
    .replace(/^#+\s*/, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

