  if (normalize(firstLine) === normalize(h1)) {
    nextGenerated.h1 = '';
  }
}

const strict = !!input.strict;

const checks = [
  { label: 'влияет', re: /\bвлия(ет|ют|ние|ющий|ющая|ющие|ющих)\b/giu },
  { label: 'помогает', re: /\bпомога(ет|ют|ющий|ющая|ющие|ющих)\b/giu },
  { label: 'обеспечивает', re: /\bобеспеч(ивает|ивают|ивающий|ивающая|ивающие|ивающих|ить|ение|ения|ению|ением)\b/giu },
  { label: 'контроль', re: /\bконтрол(ь|я|ю|ем|ировать|ируется|ируются|ирующий|ирующая|ирующие)\b/giu },
  { label: 'безопасность', re: /\bбезопасност(ь|и|ью)\b/giu },
  { label: 'оптимальный', re: /\bоптимальн(ый|ая|ое|ые|ого|ых|ому|ыми)\b/giu },
  { label: 'специализированный', re: /\bспециализированн(ый|ая|ое|ые|ого|ых|ому|ыми)\b/giu },
  { label: 'аккуратный', re: /\bаккуратн(ый|ая|ое|ые|ого|ых|ому|ыми|о|ой)\b/giu },
  { label: 'надёжный', re: /\bнад[её]жн(ый|ая|ое|ые|ого|ых|ому|ыми|ость|ости)\b/giu },
  { label: 'сохранность', re: /\bсохранност(ь|и|ью)\b/giu },
  { label: 'защита от повреждений', re: /\bзащит(а|у|ой|ы)\s+от\s+поврежден(ий|ия|иями)\b/giu },

  { label: 'удобство', re: /\bудобств(о|а|у|ом)\b/giu },
  { label: 'удобный', re: /\bудобн(ый|ая|ое|ые|ого|ых|ому|ыми|о)\b/giu },
  { label: 'оперативность', re: /\bоперативност(ь|и|ью)\b/giu },
  { label: 'оперативный', re: /\bоперативн(ый|ая|ое|ые|ого|ых|ому|ыми|о)\b/giu },
  { label: 'позволяет', re: /\bпозволя(ет|ют|ющий|ющая|ющее|ющие|ющих)\b/giu },
  { label: 'адаптировать', re: /\bадаптир(овать|ует|уют|уется|уются|ировать|ируется|ируются|ация|ации)\b/giu },
  { label: 'подходит', re: /\bподход(ит|ят|ящий|ящая|ящее|ящие|ящих)\b/giu },
  { label: 'важный', re: /\bважн(ый|ая|ое|ые|ого|ых|ому|ыми|о|а)\b/giu },
  { label: 'гибкость', re: /\bгибкост(ь|и|ью)\b/giu },
  { label: 'широкий ассортимент', re: /\bширок(ий|ого|ому|им)\s+ассортимент\b/giu }
];

const details = [];

if (strict) {
  for (const check of checks) {
    const matches = text.match(check.re) || [];

    for (const match of matches) {
      details.push({
        label: check.label,
        match: String(match).trim()
      });
    }
  }
}

const uniqueMap = new Map();

for (const item of details) {
  const key = `${item.label}::${item.match.toLowerCase()}`;
  if (!uniqueMap.has(key)) uniqueMap.set(key, item);
}

const uniqueDetails = [...uniqueMap.values()];
const violations = [...new Set(uniqueDetails.map(item => item.match.toLowerCase()))];
const labels = [...new Set(uniqueDetails.map(item => item.label))];

let seoqa = input.seoqa || {};
let factcheck = input.factcheck || {};

if (strict && violations.length > 0) {
  seoqa = {
    ...seoqa,
    verdict: 'reject',
    score: Math.min(Number(seoqa.score || 100), 70),
    summary: [
      `FINAL STRICT GATE: SEO QA понижен до reject, потому что в финальном тексте найдены strict-маркеры: ${violations.join(', ')}.`,
      seoqa.summary || ''
    ].filter(Boolean).join('\n\n'),
    problems: uniqueStrings([
      ...arr(seoqa.problems),
      `FINAL STRICT GATE violation: ${violations.join(', ')}`
    ]),
    fixes: uniqueStrings([
      ...arr(seoqa.fixes),
      'Удалить запрещённые strict-маркеры из финального текста или заменить их на нейтральные формулировки.'
    ])
  };

  factcheck = {
    ...factcheck,
    verdict: 'approved_with_warnings',
    summary: [
      factcheck.summary || '',
      `Final strict gate: найдены запрещённые маркеры: ${violations.join(', ')}.`
    ].filter(Boolean).join('\n'),
    risky_claims: uniqueStrings([
      ...arr(factcheck.risky_claims),
      ...violations.map(item => `Запрещённый strict-маркер: "${item}"`)
    ]),
    recommended_removals: uniqueStrings([
      ...arr(factcheck.recommended_removals),
      'Удалить strict-маркеры из финального текста.'
    ])
  };
}

return [{
  json: {
    ...input,
    generated_text: {
      ...nextGenerated,
      content_markdown: text,
      'content-markdown': text
    },
    seoqa,
    factcheck,
    normalize_run_output: {
      applied: true,
      version: 'v13-final-strict-gate-v1',
      strict,
      strict_count: violations.length,
      strict_labels: labels,
      strict_violations: violations,
      seoqa_forced_reject: strict && violations.length > 0
    }
  }
}];

