function clonePlain(v) {
  return JSON.parse(JSON.stringify(v));
}

function escapeRegExp(s) {
  return String(s || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function compileFamily(family) {
  return {
    id: family.id,
    label: family.label,
    severity: family.severity || 'hard',
    re: new RegExp(family.stem, family.flags || 'giu')
  };
}

function snippetAround(text, index, len) {
  const start = Math.max(0, index - 40);
  const end = Math.min(text.length, index + len + 40);
  return text.slice(start, end).replace(/\s+/g, ' ').trim();
}

function scanText(text, families, surface, fieldPath) {
  const residuals = [];
  const raw = String(text || '');
  if (!raw) return residuals;
  for (const fam of families) {
    fam.re.lastIndex = 0;
    let m;
    while ((m = fam.re.exec(raw)) !== null) {
      residuals.push({
        marker_family_id: fam.id,
        marker_label: fam.label,
        match: m[0],
        surface: surface,
        field_path: fieldPath,
        snippet: snippetAround(raw, m.index, m[0].length),
        severity: fam.severity
      });
      if (m[0].length === 0) fam.re.lastIndex += 1;
      if (residuals.length > 200) return residuals;
    }
  }
  return residuals;
}

function buildFamilyList(customMarkers) {
  const families = STRICT_MARKER_SOT.families.map(compileFamily);
  const customs = Array.isArray(customMarkers) ? customMarkers : [];
  for (let i = 0; i < customs.length; i++) {
    const c = customs[i] || {};
    const stem = c.stem || c.token || c.label;
    if (!stem) continue;
    families.push(compileFamily({
      id: c.id || ('custom-' + i),
      label: c.label || String(stem),
      stem: escapeRegExp(String(stem)),
      flags: c.flags || 'giu',
      severity: 'custom'
    }));
  }
  return families;
}

function collectScanTargets(publicPayload) {
  const surfaces = (publicPayload && publicPayload.surfaces) || {};
  const targets = [];
  if (surfaces.seo_tz) targets.push({ surface: 'seo_tz', field_path: 'surfaces.seo_tz', text: surfaces.seo_tz });
