function parseRepairContent(raw) {
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) {
    if (raw.repaired_surfaces || raw.status) return raw;
    if (raw.choices && raw.choices[0] && raw.choices[0].message) {
      return parseRepairContent(raw.choices[0].message.content);
    }
    if (raw.body && raw.body.choices && raw.body.choices[0] && raw.body.choices[0].message) {
      return parseRepairContent(raw.body.choices[0].message.content);
    }
  }
  let text = String(raw || '').trim();
  const fence = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) text = fence[1].trim();
  try {
    return JSON.parse(text);
